"""Independent central-tendency teaching and complete-answer practice for 9709 S1."""
from fractions import Fraction as F
from statistics import median
from collections import Counter
import sympy as s
from s1_representation_teaching import stem,table
lessons,questions,models=[],[],[]

def tex(v):return s.latex(s.Rational(v.numerator,v.denominator) if isinstance(v,F) else s.sympify(v))
def math(v):return r'\('+tex(v)+r'\)'
def data(a):return ', '.join(str(v) for v in a)
def picture(name,alt):return '<p><img src="/assets/original/s1-central-tendency/'+name+'.svg" alt="'+alt+'"></p>'
def ex(title,question,solution,key):return dict(title=title,question=question,solution=solution,verification=key)
def lesson(key,title,summary,ideas,mistakes,examples):
 lessons.append(dict(key=key,id='orig_9709_s1_ct_'+key,title=title,summary=summary,objective=summary,before='<p>Order data, read a frequency table and retain exact fractions. Mixed-topic written tasks also use descriptive variance and SD, introduced in the first lesson.</p>',ideas=ideas,method='<ol><li>Identify the observation count, measurement units and requested measure.</li><li>Keep exact totals and distinguish raw values from grouped estimates.</li><li>Restore every original count, coding or value condition.</li><li>State the complete result and justify a contextual choice separately.</li></ol>',mistakes=mistakes,examples=examples))

lesson('centre_raw','Mean, median, mode and choosing a centre',
 'Calculate the complete measures of centre and choose a summary that answers the actual statistical question.',
 r'''<h3>Mean, median and mode answer different questions</h3>\[\bar{x}=\frac{\sum x}{n}.\]<p>The mean uses every numerical observation. Find the median only after ordering the data: for even n average the two central observations. The mode is the most frequent observed value. Give every tied mode when the greatest frequency exceeds one; if all values occur once, this chapter uses the convention of no mode.</p>
 <h3>A modal class uses density when widths differ</h3><p>For grouped continuous data the book defines the modal class as the class with greatest frequency density. The class with the greatest frequency can be different. With equal widths both comparisons agree; if all densities are equal there is no unique modal class.</p>'''+picture('modal-density','The tallest density bar need not have the greatest frequency')+r'''
 <h3>Choose in context</h3><p>The median is less affected by the size of an extreme observation. The mean can be useful when a total matters; the mode can describe the most common category. Do not declare one measure universally best. Explain what typical means in the question.</p>
 <h3>Descriptive spread primer for mixed tasks</h3>\[\sigma^2=\frac{\sum x^2}{n}-\bar{x}^{\,2},\qquad\sigma=\sqrt{\sigma^2}.\]<p>Use divisor n here, not n−1. SD has the original units; variance has squared units. Some written questions deliberately combine this chapter with Measures of variation. A correct centre does not by itself establish consistency.</p>''',
 ['Do not confuse the median position with its observed value.', 'List every tied mode, not just the first one noticed.', 'Unequal-width modal classes require density.', 'A high outlier does not automatically invalidate the mean for every purpose.'],[
 ex('Three different measures from one ordered set',r'<p>Find the mean, median and mode of 3, 5, 5, 7, 9, 13.</p>',r'\[\begin{aligned}\bar{x}&=\frac{42}{6}=7,\\\text{median}&=\frac{5+7}{2}=6,\\\text{mode}&=5.\end{aligned}\]<p>The median is the average of the third and fourth ordered values, not the third value alone.</p>','CT-RAW'),
 ex('A tied mode and no mode are different cases',r'<p>State the modes of 2, 2, 4, 4, 7, 9. Then consider 2, 4, 7, 9 with no repeats.</p>',r'<p>The first set has two modes, 2 and 4, each occurring twice. In the second set every value occurs once, so there is no mode under the stated convention.</p>','CT-MODES'),
 ex('An extreme value affects the mean more than the median',r'<p>Repair times are 8, 9, 10, 12 and 81 minutes. Compare mean and median as summaries of a typical repair.</p>',r'\[\bar{x}=\frac{120}{5}=24,\qquad\text{median}=10.\]<p>The mean reflects the total time, including the very long repair. For a typical individual repair, the median is less influenced by that extreme duration.</p>'+picture('raw-centres','Five repair times with mean 24 and median 10'),'CT-OUTLIER'),
 ex('The most frequent class is not always the modal class',table(['Class','Frequency'],[['0 ≤ x < 5',8],['5 ≤ x < 15',12],['15 ≤ x < 20',6]])+'<p>Find the modal class and the greatest-frequency class.</p>',r'<p>Densities are \(\frac85,\frac65,\frac65\). The modal class is \([0,5)\), while the greatest frequency is in \([5,15)\). Heights identify density, areas identify frequency.</p>','CT-MODAL-CLASS')])

lesson('coding','Coded data, scale changes and unknown observations',
 'Undo a coding in the correct direction and use separate moment equations to recover missing information.',
 r'''<h3>Translation changes the mean, not the spread</h3><p>If \(u=x-a\), then</p>\[\begin{aligned}\sum x&=na+\sum u,\\\bar{x}&=a+\bar{u},\\\sigma_x&=\sigma_u.\end{aligned}\]<p>A coded sum is not the original sum unless the offset is zero.</p>
 <h3>Scaling affects SD by an absolute multiplier</h3><p>If \(u=(x-a)/b\), write \(x=a+bu\) before decoding:</p>\[\begin{aligned}\bar{x}&=a+b\bar{u},\\\sigma_x&=|b|\sigma_u,\\\sigma_x^2&=b^2\sigma_u^2.\end{aligned}\]<p>A negative multiplier reverses order but does not produce a negative SD.</p>
 <h3>Two origins can reveal a missing count</h3>\[\sum(x-a)-\sum(x-b)=n(b-a).\]<p>Each observation contributes the same difference. Check that the recovered count is a positive integer before using it.</p>
 <h3>A sum and a square-sum give different information</h3><p>Two unknown observations usually need two independent conditions. Recover both their sum and the sum of their squares, solve the resulting quadratic and restore the requested ordering. Do not confuse \(\sum x^2\) with \((\sum x)^2\).</p>''',
 ['Undo the coding rather than applying it again.', 'Use the absolute scale factor for SD.', 'Two unknown observations need more than a sum alone.', 'Check integer counts, ordering and original moment conditions.'],[
 ex('Recover an original mean and SD from a translation',r'<p>For \(u=x-40\), \(n=8\), \(\sum u=12\), \(\sum u^2=50\). Find the original mean and SD.</p>',r'\[\bar{x}=40+\frac{12}{8}=41.5.\]\[\sigma_x=\sqrt{\frac{50}{8}-\left(\frac{12}{8}\right)^2}=2.\]<p>The translation adds 40 to the mean and leaves the SD unchanged.</p>','CT-CODE-TRANSLATION'),
 ex('Decode the scale as well as the origin',r'<p>For \(u=(x-20)/3\), \(n=5\), \(\sum u=10\), \(\sum u^2=30\). Find the original mean and SD.</p>',r'\[\bar{u}=2,\quad\sigma_u^2=6-4=2.\]\[\begin{aligned}\bar{x}&=20+3(2)=26,\\\sigma_x&=3\sqrt2.\end{aligned}\]','CT-CODE-SCALE'),
 ex('Two coded sums determine the sample size',r'<p>Given \(\sum(x-10)=30\) and \(\sum(x-15)=-10\), find n and the mean.</p>',r'\[30-(-10)=5n\quad\Rightarrow\quad n=8.\]\[\begin{aligned}\sum x&=30+10(8)=110,\\\bar{x}&=\frac{55}{4}.\end{aligned}\]<p>The difference of the two totals counts the same offset once per observation.</p>','CT-TWO-ORIGINS'),
 ex('Recover two missing observations',r'<p>Six observations have mean 6 and square-sum 256. Four values are 2, 4, 7, 9. Find the remaining a and b with \(a<b\).</p>',r'\[\begin{aligned}a+b&=36-22=14,\\a^2+b^2&=256-150=106.\end{aligned}\]\[\begin{gathered}a^2+(14-a)^2=106\\\Rightarrow\quad a=5\text{ or }9.\end{gathered}\]<p>With the specified order, \((a,b)=(5,9)\). Both moment conditions are satisfied.</p>','CT-MISSING-PAIR')])

lesson('frequency','Frequency tables, grouped estimates and median interpolation',
 'Use frequencies as counts, midpoints only as a model, and cumulative positions to locate a median.',
 r'''<h3>A frequency table still represents individual observations</h3>\[n=\sum f,\qquad\bar{x}=\frac{\sum fx}{\sum f}.\]<p>Use cumulative frequencies to locate the central observation or observations. An unweighted mean of the listed x-values ignores how often each occurs.</p>
 <h3>Grouping loses the exact positions</h3><p>Replace each class by its midpoint m only when estimating moments:</p>\[\bar{x}\approx\frac{\sum fm}{\sum f},\qquad\sigma^2\approx\frac{\sum fm^2}{\sum f}-\bar{x}^{\,2}.\]<p>The midpoint model has exact calculated moments, but these are estimates of the original raw-data moments. A modal class instead uses frequency density if widths differ.</p>
 <h3>An unknown frequency belongs in both totals</h3><p>Keep it in \(\sum f\) and in the weighted sum. Solve the supplied mean condition and reject a negative or non-integer count. Check the denominator is nonzero.</p>
 <h3>Interpolated grouped medians need an assumption</h3>\[\widehat{Q}_2=L+\frac{N/2-C}{f}\,w.\]<p>L is the median class lower boundary, C the cumulative count before it, f its frequency and w its width. This assumes uniform within-class spread. Use the stated continuous boundaries and the N/2 cumulative level; the exact median of unknown raw values is not determined.</p>''',
 ['Use total frequency as the denominator.', 'Do not treat midpoints as known original observations.', 'An unknown frequency changes the denominator too.', 'Separate a median rank, its class and its estimated measurement value.'],[
 ex('A median is read from cumulative positions',table(['Value','Frequency'],[[1,2],[2,3],[5,1]])+'<p>Find the mean, median and mode.</p>',r'\[n=6,\qquad\bar{x}=\frac{13}{6}.\]<p>The third and fourth observations are both 2, so the median is 2. The mode is also 2, because its frequency is greatest.</p>','CT-FREQUENCY'),
 ex('Estimate using weighted class midpoints',table(['Class','Frequency'],[['0 ≤ x < 10',3],['10 ≤ x < 20',5],['20 ≤ x < 40',2]])+'<p>Estimate the mean.</p>',r'<p>The midpoints are 5, 15 and 30.</p>\[\bar{x}\approx\frac{3(5)+5(15)+2(30)}{10}=15.\]<p>This does not mean every original observation equalled a midpoint.</p>','CT-GROUPED-MEAN'),
 ex('An unknown frequency occurs on both sides',r'<p>Values 1, 3, 5 have frequencies 2, k, 4. Their mean is 3.5. Find k.</p>',r'\[\begin{gathered}\frac{2+3k+20}{6+k}=\frac72\\\Rightarrow\quad44+6k=42+7k.\end{gathered}\]<p>Thus \(k=2\), giving 8 observations and the required mean. Solving only the numerator would use the wrong count.</p>','CT-UNKNOWN-FREQUENCY'),
 ex('Read an interpolated median from a grouped model',r'<p>Classes \([0,10),[10,20),[20,40)\) have frequencies 3, 5, 2. Assuming uniform spread in each class, estimate the median.</p>',r'<p>The target cumulative level is 5. Before the middle class the count is 3, so</p>\[\widehat{Q}_2=10+\frac{5-3}{5}(10)=14.\]<p>The exact raw median cannot be recovered from this table alone.</p>','CT-GROUPED-MEDIAN')])

lesson('combining','Weighted means and combined moments',
 'Combine at most two data sets through compatible totals, keeping within-group and between-group spread distinct.',
 r'''<h3>Weight group means by their counts</h3>\[\bar{x}_{\rm all}=\frac{n_A\bar{x}_A+n_B\bar{x}_B}{n_A+n_B}.\]<p>The unweighted average works only for equal group sizes or coincident means. For positive group sizes and distinct means, the combined mean lies strictly between them.</p>'''+picture('weighted-means','Group sizes determine the location of the combined mean')+r'''
 <h3>Combine square-sums, not SDs</h3>\[S_i=n_i\bar{x}_i,\qquad T_i=n_i(\sigma_i^2+\bar{x}_i^{\,2}).\]\[\sigma_{\rm all}^2=\frac{T_A+T_B}{n_A+n_B}-\bar{x}_{\rm all}^{\,2}.\]<p>Different group centres add between-group spread. Averaging the SDs misses it. Pooling two observed groups is not the same operation as adding two independent random variables.</p>
 <h3>A target mean can determine a group size</h3><p>Keep the unknown size in the total count and the weighted sum. Verify that it is a positive integer and that the target mean is feasible.</p>
 <h3>Put both groups on a common scale first</h3><p>Decode different origins or units separately, then combine original totals. Adding two differently coded sums as though they measured the same thing is invalid.</p>''',
 ['Do not average unequal-size group means without weights.', 'Never average SDs to obtain a pooled SD.', 'Between-group differences can increase pooled spread.', 'Decode both groups to compatible original units before pooling.'],[
 ex('Unequal groups pull the combined mean unequally',r'<p>Four observations have mean 10 and six have mean 20. Find the combined mean.</p>',r'\[\bar{x}=\frac{4(10)+6(20)}{10}=16.\]<p>The answer is closer to 20 because the second group is larger.</p>','CT-WEIGHTED'),
 ex('Reconstruct both moments before pooling',r'<p>A group of 3 has mean 8 and population SD 2; a group of 2 has mean 13 and population SD 3. Find the combined mean and variance.</p>',r'\[\begin{aligned}S&=24+26=50,\\T&=3(64+4)+2(169+9)\\&=560.\end{aligned}\]\[\begin{aligned}\bar{x}&=10,\\\sigma^2&=\frac{560}{5}-10^2=12.\end{aligned}\]<p>Both the within-group spread and the difference of the two centres contribute.</p>','CT-POOLED'),
 ex('Recover an unknown count from a target mean',r'<p>Six values have mean 12. An additional group has mean 18. The combined mean is 16. How many values are in the additional group?</p>',r'\[\begin{gathered}72+18n=16(6+n)\\\Rightarrow\quad n=12.\end{gathered}\]<p>The count is a positive integer and the target lies between 12 and 18.</p>','CT-INVERSE-WEIGHT'),
 ex('Different coding origins need separate decoding',r'<p>Group A has 4 values with \(\sum(x-10)=8\); B has 6 values with \(\sum(y-20)=-12\). Both measure the same quantity. Find the combined mean.</p>',r'\[\begin{aligned}S_A&=48,\\S_B&=108,\\\bar{x}_{\rm all}&=\frac{156}{10}=15.6.\end{aligned}\]<p>The sum of the two coded totals, −4, would not be an original measurement total.</p>','CT-TWO-CODES')])

lesson('changes','Corrected records, missing observations and reverse problems',
 'Update counts and both moments together, then use independent conditions to recover unknown records or constraints.',
 r'''<h3>Correcting a value changes two totals</h3><p>If a was entered but should have been b,</p>\[\begin{aligned}S_{\rm new}&=S-a+b,\\T_{\rm new}&=T-a^2+b^2.\end{aligned}\]<p>The count stays the same. Remove the erroneous square; do not add the square of the correction.</p>
 <h3>Adding or removing a record also changes n</h3><p>Adjust n, S and T together before recalculating mean and variance. An unchanged mean does not imply an unchanged SD. If one value was counted twice, remove precisely one duplicate.</p>
 <h3>Two unknown records need two moment conditions</h3><p>Use the new mean to find their sum and the new variance to reconstruct their square-sum. Solve both conditions, give the requested ordered pair and restore the original equations.</p>
 <h3>A variance constraint can become a quadratic</h3><p>Adding one unknown real observation makes the new mean and variance depend on that observation. Complete the square to find a minimum or solve an exact interval condition. This is a mixed application of 9709 P1 Quadratics; no differentiation is needed.</p>''',
 ['For a correction use b²−a², not (b−a)².', 'Removal changes the count as well as the totals.', 'An unchanged mean does not establish unchanged variance.', 'Keep both roots or the complete allowed interval, subject to the original restrictions.'],[
 ex('A correction need not change the SD',r'<p>Five records have mean 12 and square-sum 800. One recorded 8 should be 18. Find the corrected mean and SD.</p>',r'\[\begin{aligned}S_{\rm new}&=60-8+18=70,\\T_{\rm new}&=800-64+324\\&=1060.\end{aligned}\]\[\begin{aligned}\bar{x}_{\rm new}&=14,\\\sigma_{\rm new}&=\sqrt{212-196}=4.\end{aligned}\]<p>The old SD was also 4. This is a property of these data, not a general rule for corrections.</p>','CT-CORRECTION'),
 ex('Remove the observation and its place in the count',r'<p>Six observations have sum 48 and square-sum 430. Remove one observation of 8. Find the remaining mean and variance.</p>',r'\[n=5,\quad S=40,\quad T=366.\]\[\bar{x}=8,\qquad\sigma^2=\frac{366}{5}-64=\frac{46}{5}.\]<p>The mean remains 8, but the variance has changed.</p>','CT-REMOVE'),
 ex('Two added values are linked, not separate guesses',r'<p>Add a and b to 3, 4, 6, 7. The six values then have mean 6 and variance 5. Find \(a<b\).</p>',r'\[\begin{aligned}a+b&=36-20=16,\\a^2+b^2&=6(5+36)-110\\&=136.\end{aligned}\]<p>Substituting \(b=16-a\) gives roots 6 and 10. The ordered answer is \((a,b)=(6,10)\).</p>','CT-ADD-PAIR'),
 ex('Complete the variance square',r'<p>Add a real value t to 2, 4, 6. Find the smallest possible population variance and all t for which it is at most 5.</p>',r'\[\begin{aligned}V(t)&=\frac{56+t^2}{4}-\left(\frac{12+t}{4}\right)^2\\&=2+\frac3{16}(t-4)^2.\end{aligned}\]<p>The minimum is 2 at \(t=4\). The inequality reduces to \((t-4)^2\le16\), giving \(0\le t\le8\). The existing unequal observations prevent a zero minimum variance.</p>','CT-VARIANCE-QUADRATIC')])

def field(key,label,kind,value,**extra):return dict(key=key,label=label,type=kind,expected=str(value),**extra)
def modes(a):
 c=Counter(a);highest=max(c.values());return [] if highest==1 else sorted(k for k,v in c.items() if v==highest)
def aset(a):return '{'+','.join(str(v) for v in a)+'}'
def show(f):
 v=f['expected']
 if f['type']=='choice':return f['options'][v]
 if f['type']=='set':
  if v.startswith('{'):return r'\(\{'+', '.join(tex(a) for a in v[1:-1].split(','))+r'\}\)'
  return r'\('+v[0]+', '.join(tex(a) for a in v[1:-1].split(','))+v[-1]+r'\)'
 if f['type']=='pairs':return r'\('+', '.join(tex(a) for a in v.split(';'))+r'\)'
 return math(v)
def quick(topic,family,v,title,prompt,fields,explanation,model):
 uid=f'M4U-9709-S1-CT-CHECK-{topic.upper()}-{family}-{v}'
 answer=''.join('<p>'+f['label']+': '+show(f)+'</p>' for f in fields)
 questions.append(dict(id=uid,family_uid=f'M4U-9709-S1-CT-CHECK-{topic.upper()}-{family}',lesson=topic,title=title,collection='short' if v==0 else 'variant',prompt_html=prompt,answer_html=answer,solution_html='<p>'+explanation+'</p><h4>Complete answers</h4>'+answer,hint_html='<p>Use the correct count and exact totals. Keep the order, coding direction and any distinction between raw and grouped estimates.</p>',marks=len(fields),difficulty=2,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='B1',marks=1,description_html='Complete correct answer for '+f['label']+'.') for f in fields])],verification=uid))
 models.append(dict(uid=uid,**model))

for v in range(2):
 a=[2,4,4,7,9,10] if v==0 else [1,3,3,5,5,7]
 quick('centre_raw',1,v,'All three measures of centre','<p>For '+data(a)+', give the exact mean, median and every mode.</p>',[field('mean','Mean','number',F(sum(a),len(a))),field('median','Median','number',F(median(a))),field('modes','All modes as a set','set',aset(modes(a)))],'Order the observations for the median and count repetitions for all tied modes. The mean uses the full total.',dict(kind='raw',data=a))
 a=[6,7,8,9,70] if v==0 else [10,12,13,15,100]
 quick('centre_raw',2,v,'An extreme duration and a typical observation','<p>Durations in minutes are '+data(a)+'. Give mean and median, then choose the more resistant summary of a typical individual duration.</p>',[field('mean','Mean duration','number',F(sum(a),len(a))),field('median','Median duration','number',F(median(a))),field('choice','Resistant summary','choice','B' if v==0 else 'C',options={'A':'Mean, because extremes never affect it','B':'Median, because the size of the extreme has less direct influence','C':'Mode, because the largest value is always modal'} if v==0 else {'A':'Mean, because it ignores the largest value','B':'The maximum, because it is typical','C':'Median, because the size of the extreme has less direct influence'})],'The mean is affected by every value, including the size of an extreme. Choosing a summary also needs the purpose stated in the question.',dict(kind='outlier',data=a,choice='B' if v==0 else 'C'))
 edges,freq=([0,5,15,20],[8,12,6]) if v==0 else ([0,4,12,20],[5,12,16]);dens=[F(freq[i],edges[i+1]-edges[i]) for i in range(3)];j=dens.index(max(dens));k=freq.index(max(freq))
 quick('centre_raw',3,v,'Modal class versus greatest frequency',table(['Class','Frequency'],[[f'{edges[i]} ≤ x < {edges[i+1]}',freq[i]] for i in range(3)])+'<p>Give all three densities, the modal class and the class with greatest frequency. Use the shown half-open intervals.</p>',[field('d'+str(i+1),'Density '+str(i+1),'number',d) for i,d in enumerate(dens)]+[field('modal','Modal class','set',f'[{edges[j]},{edges[j+1]})'),field('frequency','Greatest-frequency class','set',f'[{edges[k]},{edges[k+1]})')],'Use density for the modal class under the book definition. Frequency is represented by bar area, and can select another class.',dict(kind='modal_class',edges=edges,freq=freq))
 a=[11,13,14,17,20,22,25,30] if v==0 else [20,23,24,25,29,31,33,33,35,40];n=len(a);pair=(a[n//2-1],a[n//2])
 quick('centre_raw',4,v,'Both central observations matter','<p>Read the diagram. Give the total count, the ordered pair of central observations (lower, upper), and the median.</p>'+stem(a),[field('count','Number of observations','number',n),field('central','Ordered central pair (lower,upper)','pairs',str(pair)),field('median','Median value','number',F(sum(pair),2))],'Count all leaves, including repetitions. For an even total use both central positions and average their values.',dict(kind='even_median',data=a))

 n,C,Q,offset=(10,20,80,30) if v==0 else (8,-16,64,50);mu=F(C,n);var=F(Q,n)-mu*mu
 quick('coding',1,v,'Undo an origin shift',r'<p>For \(u=x-'+str(offset)+r'\), n='+str(n)+r', \(\sum u='+str(C)+r'\), \(\sum u^2='+str(Q)+r'\). Give the original mean, population SD and original sum.</p>',[field('mean','Original mean','number',offset+mu),field('sd','Original population SD','number',s.sqrt(s.Rational(var.numerator,var.denominator))),field('sum','Original sum','number',n*offset+C)],'Add the origin to the coded mean, not to the SD. Reconstruct the total using the origin once per observation.',dict(kind='translation',n=n,C=C,Q=Q,offset=offset))
 n,C,Q,a,b=(5,10,30,20,3) if v==0 else (4,8,24,50,-2);mu=F(C,n);var=F(Q,n)-mu*mu
 quick('coding',2,v,'A scale can be negative while SD is positive',r'<p>Given \(u=\frac{x-'+str(a)+'}{'+str(b)+r'}\), n='+str(n)+r', \(\sum u='+str(C)+r'\), \(\sum u^2='+str(Q)+r'\), recover the original mean, variance and SD exactly.</p>',[field('mean','Original mean','number',a+b*mu),field('variance','Original population variance','number',b*b*var),field('sd','Original population SD','number',abs(b)*s.sqrt(s.Rational(var.numerator,var.denominator)))],'Write the inverse code first. Variance multiplies by the square of the scale and SD by its absolute value.',dict(kind='affine',n=n,C=C,Q=Q,a=a,b=b))
 a,b,Ca,Cb=(20,24,30,-10) if v==0 else (5,9,18,-6);n=F(Ca-Cb,b-a);mu=a+F(Ca,n)
 quick('coding',3,v,'Two origins reveal a missing count',r'<p>For the same observations, \(\sum(x-'+str(a)+')='+str(Ca)+r'\) and \(\sum(x-'+str(b)+')='+str(Cb)+r'\). Give the count and the mean.</p>',[field('count','Number of observations','number',n),field('mean','Original mean','number',mu)],'Subtract the two coded sums. The offset difference occurs once for every observation; check that the count is a positive integer.',dict(kind='two_origins',a=a,b=b,Ca=Ca,Cb=Cb))
 known,pair=([1,3,5,7],(4,10)) if v==0 else ([2,4,6,8],(9,13));n=6;S=sum(known)+sum(pair);Q=sum(z*z for z in known+list(pair));mu=F(S,n)
 quick('coding',4,v,'Two missing values require both moments','<p>Six observations include '+data(known)+', with two missing values a&lt;b. The mean is '+math(mu)+' and square-sum is '+math(Q)+'. Give the missing-value sum, missing square-sum and ordered pair (a,b).</p>',[field('sum','Sum of the two missing values','number',sum(pair)),field('squares','Sum of their squares','number',sum(z*z for z in pair)),field('pair','Ordered missing pair (a,b)','pairs',str(pair))],'Reconstruct both remaining totals. Substituting the sum into the square-sum condition gives a quadratic; retain the specified order.',dict(kind='missing_pair',known=known,n=n,mean=str(mu),Q=Q))

 values,freq=([0,2,4],[1,4,3]) if v==0 else ([1,3,6],[3,2,1]);raw=[z for z,f in zip(values,freq) for _ in range(f)];n=len(raw)
 quick('frequency',1,v,'A discrete frequency table represents all observations',table(['Value','Frequency'],list(zip(values,freq)))+'<p>Give the total count, exact mean, median and all modes.</p>',[field('count','Total observations','number',n),field('mean','Mean','number',F(sum(raw),n)),field('median','Median','number',F(median(raw))),field('modes','All modes','set',aset(modes(raw)))],'Use frequencies as repetition counts; locate the middle positions in the expanded ordered data.',dict(kind='frequency',values=values,freq=freq))
 edges=[0,10,20,40];freq=[2,3,5] if v==0 else [4,4,2];mid=[F(edges[i]+edges[i+1],2) for i in range(3)];n=sum(freq);mu=sum(f*m for f,m in zip(freq,mid))/n;var=sum(f*m*m for f,m in zip(freq,mid))/n-mu*mu
